from collections import Counter

reader = PdfReader("workspace/sc100-blank.pdf")
for i, page in enumerate(reader.pages, start=1):
    annots = page.get("/Annots")
    if not annots:
        continue
    arr = annots.get_object()
    names = []
    for annot in arr:
        obj = annot.get_object()
        t = obj.get("/T")
        ft = obj.get("/FT")
        if t is not None and ft is not None:
            names.append((str(t), str(ft)))
    print(f"--- page {i} ---")
    for t, ft in names:
        print(f"   {t!r}  {ft}")
    # duplicates
    c = Counter(t for t,_ in names)
    dups = {k:v for k,v in c.items() if v>1}
    if dups:
        print("   DUPES ON THIS PAGE:", dups)

