r = PdfReader("workspace/sc100-blank.pdf")

def qn(obj):
    parts=[]; cur=obj
    while cur is not None:
        t=cur.get("/T")
        if t is None: break
        parts.append(str(t)); cur=cur.get("/Parent")
        if cur is not None: cur=cur.get_object()
    return ".".join(reversed(parts))

