    for annot in r.pages[i].get("/Annots").get_object():
        o=annot.get_object()
        if o.get("/FT")=="/Btn":
            p=o.get("/Parent")
            if p is not None:
                po=p.get_object()
                print(f"page{i+1}: annot={qn(o)!r} -> parent /T={po.get('/T')!r} parentFT={po.get('/FT')!r} parentV={po.get('/V')!r}")
print()
